import { useCallback, useEffect, useRef, useState } from 'react';

export type Phase = 'work' | 'rest';

export interface Lap {
  id: number;
  phase: Phase;
  seconds: number;
}

export function useIntervalTimer(workSeconds: number, restSeconds: number) {
  const [phase, setPhase] = useState<Phase>('work');
  const [remaining, setRemaining] = useState(workSeconds);
  const [running, setRunning] = useState(false);
  const [laps, setLaps] = useState<Lap[]>([]);
  const lapId = useRef(0);

  useEffect(() => {
    if (!running) return undefined;
    const id = setInterval(() => {
      setRemaining(prev => {
        if (prev > 1) return prev - 1;
        // Phase switch: record the finished interval as a lap.
        setPhase(current => {
          const next: Phase = current === 'work' ? 'rest' : 'work';
          setLaps(prevLaps => [
            { id: ++lapId.current, phase: current, seconds: current === 'work' ? workSeconds : restSeconds },
            ...prevLaps,
          ]);
          return next;
        });
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(id);
  }, [running, workSeconds, restSeconds]);

  const start = useCallback(() => setRunning(true), []);
  const pause = useCallback(() => setRunning(false), []);
  const reset = useCallback(() => {
    setRunning(false);
    setPhase('work');
    setRemaining(workSeconds);
    setLaps([]);
  }, [workSeconds]);

  const total = phase === 'work' ? workSeconds : restSeconds;
  const progress = total > 0 ? (total - remaining) / total : 0;

  return { phase, remaining, running, laps, progress, start, pause, reset };
}

import { View, Text, TouchableOpacity, StyleSheet, SafeAreaView, ScrollView } from 'react-native';
import { useIntervalTimer } from '../hooks/useIntervalTimer';

const colors = {
  bg: '#0f120e',
  accent: '#f05039',
  success: '#4ade80',
  border: '#242a24',
  text: '#f5f5f0',
  muted: '#8a8f8a',
  textSoft: '#d8dbd4',
}

const WORK = 30;
const REST = 15;

function format(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

export function WorkoutTimerScreen(): JSX.Element {
  const { phase, remaining, running, laps, progress, start, pause, reset } = useIntervalTimer(WORK, REST);

  return (
    <SafeAreaView style={styles.safe}>
      <ScrollView contentContainerStyle={styles.content}>
        <Text style={[styles.phase, phase === 'rest' && styles.restPhase]}>{phase.toUpperCase()}</Text>
        <View style={styles.timerRing} accessibilityLabel={`${phase} ${format(remaining)} remaining`}>
          <View style={[styles.timerFill, { transform: [{ rotate: `${progress * 360}deg` }] }]} />
          <View style={styles.timerCenter}>
            <Text style={styles.timerText}>{format(remaining)}</Text>
          </View>
        </View>
        <View style={styles.controls}>
          {running ? (
            <TouchableOpacity style={styles.control} onPress={pause} accessibilityRole="button" accessibilityLabel="Pause">
              <Text style={styles.controlText}>Pause</Text>
            </TouchableOpacity>
          ) : (
            <TouchableOpacity style={styles.control} onPress={start} accessibilityRole="button" accessibilityLabel="Start">
              <Text style={styles.controlText}>Start</Text>
            </TouchableOpacity>
          )}
          <TouchableOpacity style={styles.control} onPress={reset} accessibilityRole="button" accessibilityLabel="Reset">
            <Text style={styles.controlText}>Reset</Text>
          </TouchableOpacity>
        </View>
        {laps.length > 0 && (
          <View style={styles.laps}>
            <Text style={styles.lapsTitle}>Laps</Text>
            {laps.map(lap => (
              <View key={lap.id} style={styles.lap}>
                <Text style={styles.lapPhase}>{lap.phase}</Text>
                <Text style={styles.lapTime}>{format(lap.seconds)}</Text>
              </View>
            ))}
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  content: { alignItems: 'center', padding: 20 },
  phase: { fontSize: 18, fontWeight: '800', color: colors.accent, letterSpacing: 2 },
  restPhase: { color: colors.success },
  timerRing: { width: 220, height: 220, borderRadius: 110, borderWidth: 12, borderColor: colors.border, alignItems: 'center', justifyContent: 'center', marginVertical: 24, position: 'relative', overflow: 'hidden' },
  timerFill: { position: 'absolute', top: -12, left: -12, right: -12, bottom: -12, borderRadius: 110, borderWidth: 12, borderLeftColor: 'transparent', borderBottomColor: 'transparent', borderRightColor: 'transparent', borderTopColor: colors.accent },
  timerCenter: { alignItems: 'center' },
  timerText: { fontSize: 44, fontWeight: '800', color: colors.text, fontVariant: ['tabular-nums'] },
  controls: { flexDirection: 'row', gap: 12 },
  control: { backgroundColor: colors.accent, borderRadius: 24, paddingHorizontal: 28, paddingVertical: 12 },
  controlText: { color: colors.bg, fontWeight: '700' },
  laps: { alignSelf: 'stretch', marginTop: 24 },
  lapsTitle: { color: colors.muted, fontSize: 12, marginBottom: 8 },
  lap: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 8, borderBottomWidth: 1, borderBottomColor: colors.border },
  lapPhase: { color: colors.textSoft, textTransform: 'capitalize' },
  lapTime: { color: colors.muted, fontVariant: ['tabular-nums'] },
});
